int lengthOfLongestSubstring_BruteForce(std::string s) {
    int n = s.length();
    int maxLength = 0;
    for (int i = 0; i < n; i++) {
        std::unordered_set<char> charSet;
        for (int j = i; j < n; j++) {
            if (charSet.count(s[j])) {
                break; // Found repetition, move to next starting position
            }
            charSet.insert(s[j]);
            maxLength = std::max(maxLength, j - i + 1);
        }
    }
    return maxLength;
}

