class Solution {
public:
    int lengthOfLongestSubstring(std::string s) {
        if (s.empty()) return 0;
        std::unordered_map<char, int> charIndexMap; // Stores char -> index
        int maxLength = 0;
        int left = 0;

        for (int right = 0; right < s.length(); ++right) {
            char currentChar = s[right];

            if (charIndexMap.count(currentChar)) {
                // Update left pointer to be 1 past the previous occurrence.
                // std::max ensures left only moves forward.
                left = std::max(left, charIndexMap[currentChar] + 1);
            }

            // Update the index of the current character
            charIndexMap[currentChar] = right;

            // Calculate current substring length
            maxLength = std::max(maxLength, right - left + 1);
        }
        return maxLength;
    }
};

